func SxGap(b *port.Bitmap, cnt *port.Cells) int32 {
	// Where the text of a strip starts: the middle column of the widest run of columns (circular) that hold almost no ink (at most a twenty-fifth of the busiest
	// column's) when it is at least `sx-gap-min` wide, else three quarters of the width (9 o'clock, the left of a ring's text). `cnt` is scratch, one cell a column.
	var w int32 = port.BitmapW(b)
	var h int32 = port.BitmapH(b)
	var x int32 = 0
	var y int32 = 0
	var n int32 = 0
	var top int32 = 0
	var run int32 = 0
	var best int32 = 0
	var bestat int32 = 0
	var lim int32 = 0
	var i int32 = 0
	port.CellsDrop(cnt, 0)
	for x < w {
		y = 0
		n = 0
		for y < h {
			if port.BitmapU8(b, x, y, 0) < SxDark() {
				n += 1
			}
			y += 1
		}
		port.CellsPush(cnt, n)
		if n > top {
			top = n
		}
		x += 1
	}
	if top == 0 {
		return (w * 3) / 4
	}
	lim = top / 25
	// the runs of quiet columns, round the end: start at the first busy column so that none is cut by the seam
	x = 0
	for (x < w) && (port.CellsAt(cnt, x) <= lim) {
		x += 1
	}
	if x == w {
		return (w * 3) / 4
	}
	i = 0
	run = 0
	for i < w {
		if port.CellsAt(cnt, (x+i)%w) <= lim {
			run += 1
		} else {
			if run > best {
				best = run
				bestat = (x + i) - run
			}
			run = 0
		}
		i += 1
	}
	if run > best {
		best = run
		bestat = (x + w) - run
	}
	if best < SxGapMin() {
		return (w * 3) / 4
	}
	return (bestat + (best / 2)) % w
}

